import{_ as e,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D6.3 · 设备撤销、密钥轮换与安全迁移","description":"Hearth D6.3 开发增量：丢失设备可以被立即撤销；用户能重新配对、轮换密钥，并确认旧设备无法继续访问任务、记忆和凭据。","frontmatter":{"title":"D6.3 · 设备撤销、密钥轮换与安全迁移","description":"Hearth D6.3 开发增量：丢失设备可以被立即撤销；用户能重新配对、轮换密钥，并确认旧设备无法继续访问任务、记忆和凭据。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-6/d6-3.md","filePath":"delivery/stage-6/d6-3.md","lastUpdated":1793797632000}'),r={name:"delivery/stage-6/d6-3.md"};function s(d,a,o,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[l(`<p class="eyebrow">STAGE 6 · D6.3 · 3 / 6</p><h1 id="d6-3-·-设备撤销、密钥轮换与安全迁移" tabindex="-1">D6.3 · 设备撤销、密钥轮换与安全迁移 <a class="header-anchor" href="#d6-3-·-设备撤销、密钥轮换与安全迁移" aria-label="Permalink to &quot;D6.3 · 设备撤销、密钥轮换与安全迁移&quot;">​</a></h1><p class="lead">丢失设备必须能被立即切断审批、接管和读取能力，密钥轮换不能破坏历史事件的可验证性。</p><p class="page-meta">STAGE 6 · D6.3 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>丢失设备可以被立即撤销；用户能重新配对、轮换密钥，并确认旧设备无法继续访问任务、记忆和凭据。</div><div><strong>完成门槛</strong>撤销立即可靠；旧设备无法审批、接管或读取新事件；密钥轮换不破坏历史事件；安全事件有可读审计。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>丢失设备可以被立即撤销；用户能重新配对、轮换密钥，并确认旧设备无法继续访问任务、记忆和凭据。</p><p>Stage 6 把单机产品变成长期驻留、可迁移、可撤销的个人 Agent OS；多设备是同一逻辑身份的能力扩展，不是复制多个 Agent。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>单设备的安装、恢复、备份、安全和升级路径已稳定。</li><li>事件、lease、fencing token、记忆版本和设备身份已有稳定契约。</li><li>多设备必须共享一个逻辑身份、事件、记忆和授权，同时不绕过审批、幂等和撤销。</li><li>D6.2 的交付物已经验收；未通过时不进入本增量。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-远程撤销与会话失效" tabindex="-1">01 · 远程撤销与会话失效 <a class="header-anchor" href="#_01-·-远程撤销与会话失效" aria-label="Permalink to &quot;01 · 远程撤销与会话失效&quot;">​</a></h3><p>用户可从任一已授权设备撤销丢失设备，服务端立即吊销会话、密钥和待执行分配，并通知相关设备停止同步。撤销记录包含原因、时间、影响任务和审计 ID；正在执行的任务转为需要人工处理，不能因设备离线而延迟失效。</p><h3 id="_02-·-密钥轮换与安全重配对" tabindex="-1">02 · 密钥轮换与安全重配对 <a class="header-anchor" href="#_02-·-密钥轮换与安全重配对" aria-label="Permalink to &quot;02 · 密钥轮换与安全重配对&quot;">​</a></h3><p>新设备配对生成新密钥，旧密钥在确认迁移后失效；历史事件用保留的公钥或签名链继续验证。重新配对需要主设备确认和短期码，不能仅凭旧设备令牌恢复；轮换失败保留旧路径但明确风险，不允许降级到无加密。</p><h3 id="_03-·-加密传输、推送与设备凭据" tabindex="-1">03 · 加密传输、推送与设备凭据 <a class="header-anchor" href="#_03-·-加密传输、推送与设备凭据" aria-label="Permalink to &quot;03 · 加密传输、推送与设备凭据&quot;">​</a></h3><p>控制面、同步和设备 RPC 使用 TLS 与端到端签名，推送中继只处理密文和最小路由元数据。设备凭据存放在系统安全存储，短期有效，不能进入日志、任务上下文或备份明文；日志和诊断导出默认脱敏。</p><h3 id="_04-·-审计、异常告警与丢失演练" tabindex="-1">04 · 审计、异常告警与丢失演练 <a class="header-anchor" href="#_04-·-审计、异常告警与丢失演练" aria-label="Permalink to &quot;04 · 审计、异常告警与丢失演练&quot;">​</a></h3><p>记录配对、登录、审批、同步、撤销、密钥轮换和异常访问，提供用户可读的设备审计。演练设备丢失、撤销未完成、旧设备重新上线、恶意重放和紧急 kill switch；确认旧设备无法审批、接管或读取新事件。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd/sync</code> — 事件游标、增量拉取、重连与投影副本</li><li><code>packages/devices/router</code> — 能力目录、路由、lease、fencing 与单写者</li><li><code>packages/devices/security</code> — 远程撤销、密钥轮换、配对与设备审计</li><li><code>packages/backup</code> — 加密备份、恢复、导出/导入与迁移清单</li><li><code>packages/upgrade</code> — schema migration、版本锁定、升级检查与回滚</li><li><code>apps/hearthd/operations</code> — 调度、配额、watchdog、日志与维护模式</li><li><code>apps/web</code> — 设备状态、健康检查、诊断导出与恢复入口</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>SyncCursor</code></td><td>deviceId、stream、lastEventId、lastSyncedAt、filterHash、resumeToken；重连不能跳过事件。</td></tr><tr><td><code>DeviceLease</code></td><td>taskId、deviceId、scope、expiresAt、fencingToken；同一执行权最多一个有效写者。</td></tr><tr><td><code>BackupManifest</code></td><td>backupId、schemaVersion、executorVersions、eventRange、artifactRoots、memoryRefs、checksum、encryption；恢复必须可验证。</td></tr><tr><td><code>MigrationPlan</code></td><td>fromVersion、toVersion、preconditions、backupRef、steps、verification、rollback；升级前必须通过检查。</td></tr><tr><td><code>HealthSnapshot</code></td><td>serviceState、disk、memory、queueDepth、stuckTasks、lastBackup、knownLimits；面向用户的健康解释。</td></tr><tr><td><code>RevocationRecord</code></td><td>deviceId、reason、requestedAt、sessionsInvalidated、keysRotated、localEraseState、auditId；撤销必须可追踪。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:sync：断线、乱序、重复、游标丢失和敏感字段过滤</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:devices：租约、</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fencing、离线交接、撤销与密钥轮换</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:backup：空库安装、恢复、迁移、升级失败和回滚</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:soak：长时间运行、资源耗尽、状态漂移和自动恢复</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-6/d6-3.html">D6.3 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：远程撤销与会话失效、密钥轮换与安全重配对、加密传输、推送与设备凭据、审计、异常告警与丢失演练。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“同步冲突或设备离线”。页面必须显示“任务显示设备与同步状态，不把离线误判为失败。”，然后按“保留本地队列、重连后按 cursor 合并，避免重复执行。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：撤销立即可靠；旧设备无法审批、接管或读取新事件；密钥轮换不破坏历史事件；安全事件有可读审计。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>远程撤销/擦除流程</li><li>密钥轮换和重新配对</li><li>设备审计与 kill switch</li><li>丢失设备演练</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 撤销立即可靠；旧设备无法审批、接管或读取新事件；密钥轮换不破坏历史事件；安全事件有可读审计。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>同步冲突或设备离线</td><td>任务显示设备与同步状态，不把离线误判为失败。</td><td>保留本地队列、重连后按 cursor 合并，避免重复执行。</td></tr><tr><td>旧设备仍可访问</td><td>设备状态标记“撤销未完成”，阻断审批和读取。</td><td>使会话失效、轮换密钥、清除本地缓存，并重新验证。</td></tr><tr><td>迁移后数据不一致</td><td>恢复进入“需要验证”，阻止对外宣称完成。</td><td>对比事件、产物、记忆与技能清单，修复后重跑迁移演练。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不把多个不一致的 Agent 包装成多设备支持。</li><li>不用同步冲突或离线队列解释重复外部动作。</li><li>不在没有迁移演练和设备撤销的情况下宣布 v1.0。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/overview.html">总体架构与数据流</a></li><li><a href="/hearth-os/architecture/durable-execution.html">持久执行与恢复</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li><li><a href="/hearth-os/reference/engineering.html">工程实施与仓库结构</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-6/d6-4.html">D6.4 · 备份、恢复、迁移与升级</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const k=e(r,[["render",s]]);export{u as __pageData,k as default};
